This PR updates type hints for `discriminator` parameter of `Field` to be in line with [Pydantic's version](https://github.com/pydantic/pydantic/blob/950a1c9eadd9b050a0a21febeb360ed469e0afbd/pydantic/fields.py#L947C32-L947C45):

```py
    discriminator: str | types.Discriminator | None = _Unset,
```

Also, added tests for callable discriminator.

---

The following code works on `master`:

```py
from collections.abc import Hashable
from typing import Annotated, Any, Literal, Union

from pydantic import Discriminator, Tag
from sqlmodel import Field, SQLModel

class Pie(SQLModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> Hashable:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

    class ThanksgivingDinner(SQLModel):
        dessert: Union[
            Annotated[ApplePie, Tag("apple")],
            Annotated[PumpkinPie, Tag("pumpkin")],
        ] = Field(
            discriminator=Discriminator(get_discriminator_value),
        )

apple_variation = ThanksgivingDinner.model_validate(
    {"dessert": {"fruit": "apple", "time_to_cook": 60, "num_ingredients": 8}}
)

pumpkin_variation = ThanksgivingDinner.model_validate(
    {"dessert": {"filling": "pumpkin", "time_to_cook": 40, "num_ingredients": 6}}
)

print(type(apple_variation.dessert))
# <class '__main__.ApplePie'>

print(type(pumpkin_variation.dessert))
# <class '__main__.PumpkinPie'>

```

.. but mypy argues with:

```
error: No overload variant of "Field" matches argument types "EllipsisType", "Discriminator"  [call-overload]
```

This PR fixes this

```python
    class Item(SQLModel, table=True):
        id: Optional[int] = Field(default=None, primary_key=True)
        value: float
        hero_id: int = Field(foreign_key="hero.id")
        hero: "Hero" = Relationship(back_populates="items")

    class Hero(SQLModel, table=True):
        id: Optional[int] = Field(default=None, primary_key=True)
        name: str
        items: list[Item] = Relationship(back_populates="hero")

        @hybrid_property
        def total_items(self):
            return sum([item.value for item in self.items], 0)

        @total_items.inplace.expression
        @classmethod
        def _total_items_expression(cls):
            return (
                select(func.coalesce(func.sum(Item.value), 0))
                .where(Item.hero_id == cls.id)
                .correlate(cls)
                .label("total_items")
            )

        @hybrid_property
        def status(self):
            return "active" if self.total_items > 0 else "inactive"

        @status.inplace.expression
        @classmethod
        def _status_expression(cls):
            return (
                select(case((cls.total_items > 0, "active"), else_="inactive"))
                .label("status")
            )
```
